   <script>
     const form = document.getElementById("contact-form");
     const statusMessage = document.getElementById("form-status");

     const fields = {
       fullName: {
         input: document.getElementById("full-name"),
         error: document.getElementById("full-name-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your full name.";
           }
           if (value.trim().length < 2) {
             return "Full name must include at least 2 characters.";
           }
           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your email address.";
           }
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }
           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phone-error"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "";
           }
           const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return "Enter a valid phone number using digits, spaces, or dashes.";
           }
           return "";
         }
       }
     };

     function setFieldState(fieldConfig, message) {
       fieldConfig.error.textContent = message;
       fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
     }

     function validateField(fieldConfig) {
       const message = fieldConfig.validate(fieldConfig.input.value);
       setFieldState(fieldConfig, message);
       return message;
     }

     Object.values(fields).forEach((fieldConfig) => {
       fieldConfig.input.addEventListener("blur", () => {
         validateField(fieldConfig);
       });

       fieldConfig.input.addEventListener("input", () => {
         if (fieldConfig.input.getAttribute("aria-invalid") === "true") {
           validateField(fieldConfig);
         }
         if (statusMessage.textContent) {
           statusMessage.textContent = "";
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const errors = Object.values(fields)
         .map((fieldConfig) => ({
           input: fieldConfig.input,
           message: validateField(fieldConfig)
         }))
         .filter((result) => result.message);

       if (errors.length > 0) {
         statusMessage.textContent = "Please correct the highlighted fields before submitting.";
         errors[0].input.focus();
         return;
       }

       statusMessage.textContent = "Thanks. Your support request has been submitted.";
       form.reset();
       Object.values(fields).forEach((fieldConfig) => {
         setFieldState(fieldConfig, "");
       });
       fields.fullName.input.focus();
     });
   </script>
